#include <iostream>
#include <regex>
#include <string>

int main() {
  std::string text = "This is a C++ file.cpp, and another file.h";
  std::regex pattern("(\w+)\.(cpp|h)"); // Matches filenames with .cpp or .h extensions
  std::smatch matches;

  while (std::regex_search(text, matches, pattern)) {
    std::cout << "Filename: " << matches[1] << ", Extension: " << matches[2] << std::endl;
    text = matches.suffix().str(); //Process remaining text
  }
  return 0;
}
